INSERT INTO `translations` (`language`, `key`, `value`) VALUES
  ('en', 'common.api.contact_details', 'Contact details (phone numbers, emails, links or social media handles) can’t be shared on BeLikeLocal. Matched people plan their trip in Messages — you can share your location there.'),
  ('es', 'common.api.contact_details', 'En BeLikeLocal no se pueden compartir datos de contacto (teléfonos, correos, enlaces ni usuarios de redes sociales). Quienes hacen match planean el viaje en Mensajes, donde también puedes compartir tu ubicación.'),
  ('fr', 'common.api.contact_details', 'Les coordonnées (téléphones, e-mails, liens ou pseudos de réseaux sociaux) ne peuvent pas être partagées sur BeLikeLocal. Les personnes en match organisent leur voyage dans Messages, où vous pouvez aussi partager votre position.'),
  ('de', 'common.api.contact_details', 'Kontaktdaten (Telefonnummern, E-Mails, Links oder Social-Media-Namen) können auf BeLikeLocal nicht geteilt werden. Matches planen ihre Tour in Nachrichten – dort kannst du auch deinen Standort teilen.'),
  ('zh', 'common.api.contact_details', 'BeLikeLocal 上不能分享联系方式（电话号码、电子邮件、链接或社交媒体账号）。配对后请在“消息”中规划行程，也可以在那里分享位置。'),
  ('it', 'common.api.contact_details', 'Su BeLikeLocal non si possono condividere recapiti (numeri di telefono, email, link o nomi utente social). Chi ha un match organizza il viaggio in Messaggi, dove puoi anche condividere la tua posizione.'),
  ('ja', 'common.api.contact_details', 'BeLikeLocal では連絡先（電話番号、メール、リンク、SNS アカウント）を共有できません。マッチした相手とは「メッセージ」でツアーを計画できます。位置情報もそこで共有できます。'),
  ('ru', 'common.api.contact_details', 'В BeLikeLocal нельзя делиться контактными данными (телефонами, email, ссылками или аккаунтами в соцсетях). После мэтча поездку планируют в «Сообщениях» — там же можно поделиться местоположением.'),
  ('ko', 'common.api.contact_details', 'BeLikeLocal에서는 연락처(전화번호, 이메일, 링크, SNS 계정)를 공유할 수 없습니다. 매칭된 사람과는 메시지에서 여행을 계획하고, 위치도 공유할 수 있어요.'),
  ('ar', 'common.api.contact_details', 'لا يمكن مشاركة بيانات الاتصال (أرقام الهاتف أو البريد الإلكتروني أو الروابط أو حسابات التواصل الاجتماعي) على BeLikeLocal. يخطّط المتطابقون لرحلتهم في الرسائل، ويمكنك مشاركة موقعك هناك.'),
  ('tr', 'common.api.contact_details', 'BeLikeLocal’da iletişim bilgileri (telefon numaraları, e-postalar, bağlantılar veya sosyal medya kullanıcı adları) paylaşılamaz. Eşleşenler turlarını Mesajlar’da planlar; konumunuzu da orada paylaşabilirsiniz.'),
  ('pt', 'common.api.contact_details', 'No BeLikeLocal não se podem partilhar contactos (números de telefone, e-mails, links ou perfis de redes sociais). Quem faz match planeia a viagem em Mensagens, onde também pode partilhar a sua localização.'),
  ('el', 'common.api.contact_details', 'Στο BeLikeLocal δεν μπορούν να κοινοποιηθούν στοιχεία επικοινωνίας (τηλέφωνα, email, σύνδεσμοι ή λογαριασμοί κοινωνικών δικτύων). Όσοι ταιριάζουν σχεδιάζουν το ταξίδι στα Μηνύματα, όπου μπορείτε να κοινοποιήσετε και την τοποθεσία σας.'),
  ('th', 'common.api.contact_details', 'BeLikeLocal ไม่อนุญาตให้แชร์ข้อมูลติดต่อ (เบอร์โทร อีเมล ลิงก์ หรือบัญชีโซเชียลมีเดีย) คู่แมตช์วางแผนทริปกันในข้อความ ซึ่งแชร์ตำแหน่งได้ด้วย'),
  ('uk', 'common.api.contact_details', 'У BeLikeLocal не можна ділитися контактними даними (телефонами, email, посиланнями чи акаунтами в соцмережах). Після метчу поїздку планують у «Повідомленнях» — там можна поділитися й місцезнаходженням.'),
  ('en', 'profile.details.contact_hint', 'Please don’t include phone numbers, emails, links or social media handles — matched people talk through BeLikeLocal’s Messages.'),
  ('es', 'profile.details.contact_hint', 'No incluyas teléfonos, correos, enlaces ni usuarios de redes sociales: quienes hacen match hablan por Mensajes de BeLikeLocal.'),
  ('fr', 'profile.details.contact_hint', 'N’indiquez pas de numéros, d’e-mails, de liens ni de pseudos : les personnes en match échangent via les Messages de BeLikeLocal.'),
  ('de', 'profile.details.contact_hint', 'Bitte keine Telefonnummern, E-Mails, Links oder Social-Media-Namen angeben – Matches schreiben sich über die Nachrichten von BeLikeLocal.'),
  ('zh', 'profile.details.contact_hint', '请勿填写电话号码、电子邮件、链接或社交媒体账号——配对的人通过 BeLikeLocal 的消息沟通。'),
  ('it', 'profile.details.contact_hint', 'Non inserire numeri, email, link o nomi utente social: chi ha un match si scrive tramite i Messaggi di BeLikeLocal.'),
  ('ja', 'profile.details.contact_hint', '電話番号、メール、リンク、SNS アカウントは書かないでください。マッチした相手とは BeLikeLocal のメッセージでやり取りします。'),
  ('ru', 'profile.details.contact_hint', 'Не указывайте телефоны, email, ссылки или аккаунты в соцсетях — после мэтча общение идёт в «Сообщениях» BeLikeLocal.'),
  ('ko', 'profile.details.contact_hint', '전화번호, 이메일, 링크, SNS 계정은 적지 마세요. 매칭된 사람과는 BeLikeLocal 메시지로 대화합니다.'),
  ('ar', 'profile.details.contact_hint', 'يُرجى عدم كتابة أرقام الهاتف أو البريد الإلكتروني أو الروابط أو حسابات التواصل — يتواصل المتطابقون عبر رسائل BeLikeLocal.'),
  ('tr', 'profile.details.contact_hint', 'Lütfen telefon numarası, e-posta, bağlantı veya sosyal medya kullanıcı adı yazmayın — eşleşenler BeLikeLocal Mesajlar üzerinden konuşur.'),
  ('pt', 'profile.details.contact_hint', 'Não inclua números de telefone, e-mails, links ou perfis de redes sociais — quem faz match fala pelas Mensagens do BeLikeLocal.'),
  ('el', 'profile.details.contact_hint', 'Μην προσθέτετε τηλέφωνα, email, συνδέσμους ή λογαριασμούς κοινωνικών δικτύων — όσοι ταιριάζουν μιλούν μέσω των Μηνυμάτων του BeLikeLocal.'),
  ('th', 'profile.details.contact_hint', 'โปรดอย่าใส่เบอร์โทร อีเมล ลิงก์ หรือบัญชีโซเชียลมีเดีย — คู่แมตช์คุยกันผ่านข้อความของ BeLikeLocal'),
  ('uk', 'profile.details.contact_hint', 'Не вказуйте телефони, email, посилання чи акаунти в соцмережах — після метчу спілкування йде в «Повідомленнях» BeLikeLocal.'),
  ('en', 'profile.details.price_amount_hint', 'The fee a visitor pays to book a trip with you. Leave it at 0 to guide for free — the trip is booked as soon as you match.'),
  ('es', 'profile.details.price_amount_hint', 'La tarifa que paga un visitante para reservar un viaje contigo. Déjala en 0 para guiar gratis: el viaje se reserva en cuanto hacéis match.'),
  ('fr', 'profile.details.price_amount_hint', 'Le tarif qu’un visiteur paie pour réserver un voyage avec vous. Laissez 0 pour guider gratuitement : le voyage est réservé dès le match.'),
  ('de', 'profile.details.price_amount_hint', 'Die Gebühr, die ein Gast zahlt, um eine Tour mit dir zu buchen. Lass 0 stehen, um kostenlos zu führen – die Tour ist dann sofort beim Match gebucht.'),
  ('zh', 'profile.details.price_amount_hint', '游客预订你的行程需支付的费用。保持为 0 即免费带团——配对后行程立即生效。'),
  ('it', 'profile.details.price_amount_hint', 'La tariffa che un visitatore paga per prenotare un viaggio con te. Lasciala a 0 per fare da guida gratis: il viaggio è prenotato appena c’è il match.'),
  ('ja', 'profile.details.price_amount_hint', 'ゲストがあなたとのツアーを予約するときに支払う料金です。0 のままにすると無料ガイドになり、マッチした時点でツアーが予約されます。'),
  ('ru', 'profile.details.price_amount_hint', 'Сумма, которую гость платит за бронирование поездки с вами. Оставьте 0, чтобы водить бесплатно — поездка бронируется сразу после мэтча.'),
  ('ko', 'profile.details.price_amount_hint', '방문객이 나와의 여행을 예약할 때 내는 요금입니다. 0으로 두면 무료 가이드가 되며, 매칭되는 즉시 여행이 예약됩니다.'),
  ('ar', 'profile.details.price_amount_hint', 'الرسوم التي يدفعها الزائر لحجز رحلة معك. اتركها 0 لترشد مجانًا — تُحجز الرحلة فور التطابق.'),
  ('tr', 'profile.details.price_amount_hint', 'Bir ziyaretçinin sizinle tur rezervasyonu için ödediği ücret. Ücretsiz rehberlik için 0 bırakın — eşleşir eşleşmez tur rezerve edilir.'),
  ('pt', 'profile.details.price_amount_hint', 'O valor que um visitante paga para reservar uma viagem consigo. Deixe 0 para guiar de graça — a viagem fica reservada assim que houver match.'),
  ('el', 'profile.details.price_amount_hint', 'Η αμοιβή που πληρώνει ένας επισκέπτης για να κλείσει ταξίδι μαζί σας. Αφήστε 0 για δωρεάν ξενάγηση — το ταξίδι κλείνει μόλις ταιριάξετε.'),
  ('th', 'profile.details.price_amount_hint', 'ค่าบริการที่ผู้มาเยือนจ่ายเพื่อจองทริปกับคุณ ปล่อยเป็น 0 หากต้องการนำเที่ยวฟรี — ทริปจะถูกจองทันทีที่แมตช์'),
  ('uk', 'profile.details.price_amount_hint', 'Сума, яку гість платить за бронювання поїздки з вами. Залиште 0, щоб водити безкоштовно — поїздку бронюють одразу після метчу.'),
  ('en', 'common.booking_panel.accepted', 'Booking confirmed — it’s in My trips. Plan the details with {name} in Messages.'),
  ('es', 'common.booking_panel.accepted', 'Reserva confirmada: está en Mis viajes. Planea los detalles con {name} en Mensajes.'),
  ('fr', 'common.booking_panel.accepted', 'Réservation confirmée : elle est dans Mes voyages. Organisez les détails avec {name} dans Messages.'),
  ('de', 'common.booking_panel.accepted', 'Buchung bestätigt – sie ist in Meine Touren. Plant die Details mit {name} in Nachrichten.'),
  ('zh', 'common.booking_panel.accepted', '预订已确认——已加入“我的行程”。请在“消息”中与 {name} 商定细节。'),
  ('it', 'common.booking_panel.accepted', 'Prenotazione confermata: è in I miei viaggi. Organizza i dettagli con {name} in Messaggi.'),
  ('ja', 'common.booking_panel.accepted', '予約が確定しました。「マイツアー」にあります。詳細は「メッセージ」で {name} さんと決めましょう。'),
  ('ru', 'common.booking_panel.accepted', 'Бронирование подтверждено — оно в «Моих поездках». Обсудите детали с {name} в «Сообщениях».'),
  ('ko', 'common.booking_panel.accepted', '예약이 확정되었습니다. 내 여행에 있어요. 세부 사항은 메시지에서 {name}님과 정하세요.'),
  ('ar', 'common.booking_panel.accepted', 'تم تأكيد الحجز — تجده في رحلاتي. خطّط للتفاصيل مع {name} في الرسائل.'),
  ('tr', 'common.booking_panel.accepted', 'Rezervasyon onaylandı — Turlarım’da. Ayrıntıları {name} ile Mesajlar’da planlayın.'),
  ('pt', 'common.booking_panel.accepted', 'Reserva confirmada — está em As minhas viagens. Combine os detalhes com {name} em Mensagens.'),
  ('el', 'common.booking_panel.accepted', 'Η κράτηση επιβεβαιώθηκε — είναι στα Ταξίδια μου. Κανονίστε τις λεπτομέρειες με τον/την {name} στα Μηνύματα.'),
  ('th', 'common.booking_panel.accepted', 'ยืนยันการจองแล้ว — อยู่ในทริปของฉัน วางแผนรายละเอียดกับ {name} ในข้อความ'),
  ('uk', 'common.booking_panel.accepted', 'Бронювання підтверджено — воно в «Моїх поїздках». Обговоріть деталі з {name} у «Повідомленнях».'),
  ('en', 'common.booking_panel.guide_awaiting_payment', 'The trip is booked once the visitor pays your {amount} fee and you confirm the date. You can chat in Messages meanwhile.'),
  ('es', 'common.booking_panel.guide_awaiting_payment', 'El viaje se reserva cuando el visitante paga tu tarifa de {amount} y confirmas la fecha. Mientras tanto podéis hablar en Mensajes.'),
  ('fr', 'common.booking_panel.guide_awaiting_payment', 'Le voyage est réservé quand le visiteur paie votre tarif de {amount} et que vous confirmez la date. En attendant, vous pouvez discuter dans Messages.'),
  ('de', 'common.booking_panel.guide_awaiting_payment', 'Die Tour ist gebucht, sobald der Gast deine Gebühr von {amount} zahlt und du den Termin bestätigst. Bis dahin könnt ihr in Nachrichten schreiben.'),
  ('zh', 'common.booking_panel.guide_awaiting_payment', '游客支付你的 {amount} 费用且你确认日期后，行程即预订成功。在此期间可在“消息”中聊天。'),
  ('it', 'common.booking_panel.guide_awaiting_payment', 'Il viaggio è prenotato quando il visitatore paga la tua tariffa di {amount} e confermi la data. Nel frattempo potete scrivervi in Messaggi.'),
  ('ja', 'common.booking_panel.guide_awaiting_payment', 'ゲストが {amount} の料金を支払い、あなたが日程を確定するとツアーが予約されます。それまでは「メッセージ」でやり取りできます。'),
  ('ru', 'common.booking_panel.guide_awaiting_payment', 'Поездка бронируется, когда гость оплатит ваши {amount} и вы подтвердите дату. Пока можно общаться в «Сообщениях».'),
  ('ko', 'common.booking_panel.guide_awaiting_payment', '방문객이 {amount} 요금을 결제하고 내가 날짜를 확정하면 여행이 예약됩니다. 그동안 메시지로 대화할 수 있어요.'),
  ('ar', 'common.booking_panel.guide_awaiting_payment', 'تُحجز الرحلة عندما يدفع الزائر رسومك البالغة {amount} وتؤكد الموعد. يمكنكما الدردشة في الرسائل في هذه الأثناء.'),
  ('tr', 'common.booking_panel.guide_awaiting_payment', 'Ziyaretçi {amount} ücretinizi ödeyip siz tarihi onayladığınızda tur rezerve edilir. Bu arada Mesajlar’da konuşabilirsiniz.'),
  ('pt', 'common.booking_panel.guide_awaiting_payment', 'A viagem fica reservada quando o visitante pagar o seu valor de {amount} e confirmar a data. Entretanto, podem falar em Mensagens.'),
  ('el', 'common.booking_panel.guide_awaiting_payment', 'Το ταξίδι κλείνει όταν ο επισκέπτης πληρώσει την αμοιβή σας των {amount} και επιβεβαιώσετε την ημερομηνία. Μέχρι τότε μπορείτε να μιλάτε στα Μηνύματα.'),
  ('th', 'common.booking_panel.guide_awaiting_payment', 'ทริปจะถูกจองเมื่อผู้มาเยือนจ่ายค่าบริการ {amount} และคุณยืนยันวัน ระหว่างนี้คุยกันในข้อความได้'),
  ('uk', 'common.booking_panel.guide_awaiting_payment', 'Поїздку бронюють, коли гість сплатить ваші {amount} і ви підтвердите дату. Поки що можна спілкуватися в «Повідомленнях».'),
  ('en', 'common.booking_panel.guide_pending_note', 'Accepting commits you to this date. Declining refunds the visitor in full.'),
  ('es', 'common.booking_panel.guide_pending_note', 'Aceptar te compromete con esta fecha. Rechazar reembolsa todo al visitante.'),
  ('fr', 'common.booking_panel.guide_pending_note', 'Accepter vous engage pour cette date. Refuser rembourse intégralement le visiteur.'),
  ('de', 'common.booking_panel.guide_pending_note', 'Mit der Annahme verpflichtest du dich zu diesem Termin. Bei Ablehnung erhält der Gast alles zurück.'),
  ('zh', 'common.booking_panel.guide_pending_note', '接受即表示你承诺这个日期。拒绝则游客获得全额退款。'),
  ('it', 'common.booking_panel.guide_pending_note', 'Accettando ti impegni per questa data. Rifiutando, il visitatore viene rimborsato per intero.'),
  ('ja', 'common.booking_panel.guide_pending_note', '承諾するとこの日程を約束したことになります。断るとゲストに全額返金されます。'),
  ('ru', 'common.booking_panel.guide_pending_note', 'Приняв, вы берёте на себя эту дату. При отказе гость получит полный возврат.'),
  ('ko', 'common.booking_panel.guide_pending_note', '수락하면 이 날짜에 확정됩니다. 거절하면 방문객에게 전액 환불됩니다.'),
  ('ar', 'common.booking_panel.guide_pending_note', 'القبول يُلزمك بهذا الموعد. والرفض يعيد للزائر المبلغ كاملًا.'),
  ('tr', 'common.booking_panel.guide_pending_note', 'Kabul etmek sizi bu tarihe bağlar. Reddederseniz ziyaretçiye tam iade yapılır.'),
  ('pt', 'common.booking_panel.guide_pending_note', 'Aceitar compromete-o com esta data. Recusar reembolsa o visitante na totalidade.'),
  ('el', 'common.booking_panel.guide_pending_note', 'Η αποδοχή σάς δεσμεύει για αυτή την ημερομηνία. Η απόρριψη επιστρέφει όλο το ποσό στον επισκέπτη.'),
  ('th', 'common.booking_panel.guide_pending_note', 'การยอมรับคือคุณให้คำมั่นกับวันนี้ การปฏิเสธจะคืนเงินเต็มจำนวนให้ผู้มาเยือน'),
  ('uk', 'common.booking_panel.guide_pending_note', 'Прийнявши, ви берете на себе цю дату. У разі відмови гість отримає повне повернення.'),
  ('en', 'common.booking_panel.paid', 'Payment of {amount} received — {name} will now confirm the date.'),
  ('es', 'common.booking_panel.paid', 'Pago de {amount} recibido: ahora {name} confirmará la fecha.'),
  ('fr', 'common.booking_panel.paid', 'Paiement de {amount} reçu — {name} va maintenant confirmer la date.'),
  ('de', 'common.booking_panel.paid', 'Zahlung von {amount} erhalten – {name} bestätigt jetzt den Termin.'),
  ('zh', 'common.booking_panel.paid', '已收到 {amount} 付款——{name} 将确认日期。'),
  ('it', 'common.booking_panel.paid', 'Pagamento di {amount} ricevuto: ora {name} confermerà la data.'),
  ('ja', 'common.booking_panel.paid', '{amount} の支払いを受け付けました。{name} さんが日程を確定します。'),
  ('ru', 'common.booking_panel.paid', 'Оплата {amount} получена — теперь {name} подтвердит дату.'),
  ('ko', 'common.booking_panel.paid', '{amount} 결제가 완료되었습니다. 이제 {name}님이 날짜를 확정합니다.'),
  ('ar', 'common.booking_panel.paid', 'تم استلام دفعة {amount} — سيؤكد {name} الموعد الآن.'),
  ('tr', 'common.booking_panel.paid', '{amount} ödemesi alındı — {name} şimdi tarihi onaylayacak.'),
  ('pt', 'common.booking_panel.paid', 'Pagamento de {amount} recebido — {name} vai agora confirmar a data.'),
  ('el', 'common.booking_panel.paid', 'Η πληρωμή {amount} ελήφθη — ο/η {name} θα επιβεβαιώσει τώρα την ημερομηνία.'),
  ('th', 'common.booking_panel.paid', 'ได้รับชำระ {amount} แล้ว — {name} จะยืนยันวันต่อไป'),
  ('uk', 'common.booking_panel.paid', 'Оплату {amount} отримано — тепер {name} підтвердить дату.'),
  ('en', 'common.booking_panel.pay_to_book_again', 'Pay {name}’s {amount} fee to book another trip. It’s confirmed once {name} accepts.'),
  ('es', 'common.booking_panel.pay_to_book_again', 'Paga la tarifa de {amount} de {name} para reservar otro viaje. Se confirma cuando {name} acepte.'),
  ('fr', 'common.booking_panel.pay_to_book_again', 'Payez le tarif de {amount} de {name} pour réserver un autre voyage. Il est confirmé quand {name} accepte.'),
  ('de', 'common.booking_panel.pay_to_book_again', 'Zahle {name}s Gebühr von {amount}, um eine weitere Tour zu buchen. Sie ist bestätigt, sobald {name} annimmt.'),
  ('zh', 'common.booking_panel.pay_to_book_again', '支付 {name} 的 {amount} 费用即可再次预订。{name} 接受后即确认。'),
  ('it', 'common.booking_panel.pay_to_book_again', 'Paga la tariffa di {amount} di {name} per prenotare un altro viaggio. È confermato quando {name} accetta.'),
  ('ja', 'common.booking_panel.pay_to_book_again', '{name} さんの料金 {amount} を支払うと、もう一度予約できます。{name} さんが承諾すると確定します。'),
  ('ru', 'common.booking_panel.pay_to_book_again', 'Оплатите {amount} гиду {name}, чтобы забронировать ещё одну поездку. Она подтверждается, когда {name} примет.'),
  ('ko', 'common.booking_panel.pay_to_book_again', '{name}님의 요금 {amount}을 결제하면 다시 예약할 수 있어요. {name}님이 수락하면 확정됩니다.'),
  ('ar', 'common.booking_panel.pay_to_book_again', 'ادفع رسوم {name} البالغة {amount} لحجز رحلة أخرى. تُؤكد عندما يقبل {name}.'),
  ('tr', 'common.booking_panel.pay_to_book_again', 'Başka bir tur için {name} kişisinin {amount} ücretini ödeyin. {name} kabul ettiğinde onaylanır.'),
  ('pt', 'common.booking_panel.pay_to_book_again', 'Pague o valor de {amount} de {name} para reservar outra viagem. Fica confirmada quando {name} aceitar.'),
  ('el', 'common.booking_panel.pay_to_book_again', 'Πληρώστε την αμοιβή {amount} του/της {name} για άλλο ένα ταξίδι. Επιβεβαιώνεται μόλις ο/η {name} αποδεχτεί.'),
  ('th', 'common.booking_panel.pay_to_book_again', 'จ่ายค่าบริการ {amount} ของ {name} เพื่อจองทริปใหม่ จะยืนยันเมื่อ {name} ยอมรับ'),
  ('uk', 'common.booking_panel.pay_to_book_again', 'Сплатіть {amount} гіду {name}, щоб забронювати ще одну поїздку. Її підтверджено, коли {name} прийме.'),
  ('en', 'common.booking_panel.pay_to_request_date', 'Pay {name}’s {amount} fee to request a date. It’s confirmed once {name} accepts.'),
  ('es', 'common.booking_panel.pay_to_request_date', 'Paga la tarifa de {amount} de {name} para pedir una fecha. Se confirma cuando {name} acepte.'),
  ('fr', 'common.booking_panel.pay_to_request_date', 'Payez le tarif de {amount} de {name} pour demander une date. Elle est confirmée quand {name} accepte.'),
  ('de', 'common.booking_panel.pay_to_request_date', 'Zahle {name}s Gebühr von {amount}, um einen Termin anzufragen. Er ist bestätigt, sobald {name} annimmt.'),
  ('zh', 'common.booking_panel.pay_to_request_date', '支付 {name} 的 {amount} 费用即可申请日期。{name} 接受后即确认。'),
  ('it', 'common.booking_panel.pay_to_request_date', 'Paga la tariffa di {amount} di {name} per richiedere una data. È confermata quando {name} accetta.'),
  ('ja', 'common.booking_panel.pay_to_request_date', '{name} さんの料金 {amount} を支払って日程をリクエストしましょう。{name} さんが承諾すると確定します。'),
  ('ru', 'common.booking_panel.pay_to_request_date', 'Оплатите {amount} гиду {name}, чтобы запросить дату. Она подтверждается, когда {name} примет.'),
  ('ko', 'common.booking_panel.pay_to_request_date', '{name}님의 요금 {amount}을 결제하고 날짜를 요청하세요. {name}님이 수락하면 확정됩니다.'),
  ('ar', 'common.booking_panel.pay_to_request_date', 'ادفع رسوم {name} البالغة {amount} لطلب موعد. يُؤكد عندما يقبل {name}.'),
  ('tr', 'common.booking_panel.pay_to_request_date', 'Bir tarih istemek için {name} kişisinin {amount} ücretini ödeyin. {name} kabul ettiğinde onaylanır.'),
  ('pt', 'common.booking_panel.pay_to_request_date', 'Pague o valor de {amount} de {name} para pedir uma data. Fica confirmada quando {name} aceitar.'),
  ('el', 'common.booking_panel.pay_to_request_date', 'Πληρώστε την αμοιβή {amount} του/της {name} για να ζητήσετε ημερομηνία. Επιβεβαιώνεται μόλις ο/η {name} αποδεχτεί.'),
  ('th', 'common.booking_panel.pay_to_request_date', 'จ่ายค่าบริการ {amount} ของ {name} เพื่อขอนัดวัน จะยืนยันเมื่อ {name} ยอมรับ'),
  ('uk', 'common.booking_panel.pay_to_request_date', 'Сплатіть {amount} гіду {name}, щоб запросити дату. Її підтверджено, коли {name} прийме.'),
  ('en', 'guide_discover.rail.subtitle', 'Mutual interest opens a chat.'),
  ('es', 'guide_discover.rail.subtitle', 'El interés mutuo abre un chat.'),
  ('fr', 'guide_discover.rail.subtitle', 'Un intérêt mutuel ouvre une discussion.'),
  ('de', 'guide_discover.rail.subtitle', 'Gegenseitiges Interesse öffnet einen Chat.'),
  ('zh', 'guide_discover.rail.subtitle', '互相感兴趣即可开始聊天。'),
  ('it', 'guide_discover.rail.subtitle', 'L’interesse reciproco apre una chat.'),
  ('ja', 'guide_discover.rail.subtitle', 'お互いに興味があればチャットが始まります。'),
  ('ru', 'guide_discover.rail.subtitle', 'Взаимный интерес открывает чат.'),
  ('ko', 'guide_discover.rail.subtitle', '서로 관심이 있으면 채팅이 열립니다.'),
  ('ar', 'guide_discover.rail.subtitle', 'الاهتمام المتبادل يفتح محادثة.'),
  ('tr', 'guide_discover.rail.subtitle', 'Karşılıklı ilgi bir sohbet başlatır.'),
  ('pt', 'guide_discover.rail.subtitle', 'O interesse mútuo abre uma conversa.'),
  ('el', 'guide_discover.rail.subtitle', 'Το αμοιβαίο ενδιαφέρον ανοίγει μια συνομιλία.'),
  ('th', 'guide_discover.rail.subtitle', 'สนใจกันทั้งสองฝ่ายจะเปิดแชทได้'),
  ('uk', 'guide_discover.rail.subtitle', 'Взаємний інтерес відкриває чат.'),
  ('en', 'guide_discover.toast.matched', 'You matched with {name}! Say hello in Messages. Once they’ve paid your fee and you’ve confirmed the date (straight away, if you don’t charge one), the trip is on your My trips page.'),
  ('es', 'guide_discover.toast.matched', '¡Has hecho match con {name}! Salúdale en Mensajes. Cuando pague tu tarifa y confirmes la fecha (al momento, si no cobras), el viaje estará en Mis viajes.'),
  ('fr', 'guide_discover.toast.matched', 'C’est un match avec {name} ! Dites bonjour dans Messages. Une fois votre tarif payé et la date confirmée (tout de suite si vous ne facturez rien), le voyage sera dans Mes voyages.'),
  ('de', 'guide_discover.toast.matched', 'Du hast ein Match mit {name}! Sag hallo in Nachrichten. Sobald die Gebühr bezahlt und der Termin bestätigt ist (sofort, wenn du nichts verlangst), steht die Tour in Meine Touren.'),
  ('zh', 'guide_discover.toast.matched', '你和 {name} 配对成功！在“消息”中打个招呼吧。对方支付费用且你确认日期后（不收费则立即），行程会出现在“我的行程”中。'),
  ('it', 'guide_discover.toast.matched', 'Hai un match con {name}! Salutalo in Messaggi. Quando avrà pagato la tua tariffa e avrai confermato la data (subito, se non chiedi nulla), il viaggio sarà in I miei viaggi.'),
  ('ja', 'guide_discover.toast.matched', '{name} さんとマッチしました！「メッセージ」であいさつしましょう。料金の支払いと日程の確定が済むと（無料なら即時）、ツアーが「マイツアー」に表示されます。'),
  ('ru', 'guide_discover.toast.matched', 'У вас мэтч с {name}! Поздоровайтесь в «Сообщениях». Когда гость оплатит ваш тариф и вы подтвердите дату (сразу, если вы работаете бесплатно), поездка появится в «Моих поездках».'),
  ('ko', 'guide_discover.toast.matched', '{name}님과 매칭되었어요! 메시지에서 인사해 보세요. 요금 결제와 날짜 확정이 끝나면(무료라면 바로) 여행이 내 여행에 표시됩니다.'),
  ('ar', 'guide_discover.toast.matched', 'تطابقت مع {name}! قل مرحبًا في الرسائل. بعد دفع رسومك وتأكيد الموعد (فورًا إذا كنت لا تتقاضى رسومًا)، ستظهر الرحلة في رحلاتي.'),
  ('tr', 'guide_discover.toast.matched', '{name} ile eşleştiniz! Mesajlar’da merhaba deyin. Ücretinizi ödeyip tarihi onayladığınızda (ücret almıyorsanız hemen) tur Turlarım’da olacak.'),
  ('pt', 'guide_discover.toast.matched', 'Fez match com {name}! Diga olá em Mensagens. Quando pagar o seu valor e confirmar a data (de imediato, se não cobrar), a viagem fica em As minhas viagens.'),
  ('el', 'guide_discover.toast.matched', 'Ταιριάξατε με τον/την {name}! Πείτε γεια στα Μηνύματα. Μόλις πληρωθεί η αμοιβή σας και επιβεβαιώσετε την ημερομηνία (αμέσως, αν δεν χρεώνετε), το ταξίδι θα είναι στα Ταξίδια μου.'),
  ('th', 'guide_discover.toast.matched', 'คุณแมตช์กับ {name} แล้ว! ทักทายในข้อความได้เลย เมื่อจ่ายค่าบริการและคุณยืนยันวันแล้ว (ทันที หากไม่เก็บค่าบริการ) ทริปจะอยู่ในทริปของฉัน'),
  ('uk', 'guide_discover.toast.matched', 'У вас метч з {name}! Привітайтеся в «Повідомленнях». Коли гість сплатить ваш тариф і ви підтвердите дату (одразу, якщо безкоштовно), поїздка з’явиться в «Моїх поїздках».'),
  ('en', 'home.hero.direct_contact', 'Chat as soon as you match'),
  ('es', 'home.hero.direct_contact', 'Chat en cuanto hacéis match'),
  ('fr', 'home.hero.direct_contact', 'Discussion dès le match'),
  ('de', 'home.hero.direct_contact', 'Chat direkt nach dem Match'),
  ('zh', 'home.hero.direct_contact', '配对后即可聊天'),
  ('it', 'home.hero.direct_contact', 'Chat appena c’è il match'),
  ('ja', 'home.hero.direct_contact', 'マッチしたらすぐチャット'),
  ('ru', 'home.hero.direct_contact', 'Чат сразу после мэтча'),
  ('ko', 'home.hero.direct_contact', '매칭되면 바로 채팅'),
  ('ar', 'home.hero.direct_contact', 'دردشة فور التطابق'),
  ('tr', 'home.hero.direct_contact', 'Eşleşir eşleşmez sohbet'),
  ('pt', 'home.hero.direct_contact', 'Conversa assim que houver match'),
  ('el', 'home.hero.direct_contact', 'Συνομιλία μόλις ταιριάξετε'),
  ('th', 'home.hero.direct_contact', 'แชทได้ทันทีที่แมตช์'),
  ('uk', 'home.hero.direct_contact', 'Чат одразу після метчу'),
  ('en', 'home.how.match_body', 'Guides browse compatible visitors too. Once interest is mutual, you chat and plan the trip right here — even share where to meet.'),
  ('es', 'home.how.match_body', 'Los guías también ven visitantes compatibles. Cuando el interés es mutuo, chateáis y planeáis el viaje aquí mismo, incluso compartiendo dónde quedar.'),
  ('fr', 'home.how.match_body', 'Les guides parcourent aussi les visiteurs compatibles. Dès que l’intérêt est mutuel, vous discutez et organisez le voyage ici, en partageant même le lieu de rendez-vous.'),
  ('de', 'home.how.match_body', 'Guides sehen auch passende Gäste. Ist das Interesse gegenseitig, chattet und plant ihr die Tour direkt hier – sogar mit geteiltem Treffpunkt.'),
  ('zh', 'home.how.match_body', '导游也会浏览合适的游客。一旦互相感兴趣，就能在这里聊天、规划行程，甚至分享集合地点。'),
  ('it', 'home.how.match_body', 'Anche le guide vedono i visitatori compatibili. Quando l’interesse è reciproco, chattate e organizzate il viaggio qui, condividendo anche il punto d’incontro.'),
  ('ja', 'home.how.match_body', 'ガイドも相性の良いゲストを探しています。お互いに興味があれば、ここでチャットしてツアーを計画し、集合場所も共有できます。'),
  ('ru', 'home.how.match_body', 'Гиды тоже просматривают подходящих гостей. Когда интерес взаимный, вы общаетесь и планируете поездку прямо здесь — даже место встречи можно отправить.'),
  ('ko', 'home.how.match_body', '가이드도 잘 맞는 방문객을 찾아봅니다. 서로 관심이 생기면 여기서 바로 채팅하고 여행을 계획하며, 만날 장소도 공유할 수 있어요.'),
  ('ar', 'home.how.match_body', 'يتصفح المرشدون الزوار المناسبين أيضًا. عندما يكون الاهتمام متبادلًا، تتحدثان وتخططان للرحلة هنا — وحتى تشاركان مكان اللقاء.'),
  ('tr', 'home.how.match_body', 'Rehberler de uygun ziyaretçilere göz atar. İlgi karşılıklı olunca burada sohbet edip turu planlarsınız — buluşma yerini bile paylaşabilirsiniz.'),
  ('pt', 'home.how.match_body', 'Os guias também veem visitantes compatíveis. Quando o interesse é mútuo, conversam e planeiam a viagem aqui mesmo — até partilham onde se encontrar.'),
  ('el', 'home.how.match_body', 'Και οι ξεναγοί βλέπουν συμβατούς επισκέπτες. Όταν το ενδιαφέρον είναι αμοιβαίο, συνομιλείτε και σχεδιάζετε το ταξίδι εδώ — κοινοποιώντας ακόμη και το σημείο συνάντησης.'),
  ('th', 'home.how.match_body', 'ไกด์ก็เลือกดูผู้มาเยือนที่เข้ากันได้ เมื่อสนใจกันทั้งสองฝ่าย ก็แชทและวางแผนทริปได้ที่นี่ แชร์จุดนัดพบได้ด้วย'),
  ('uk', 'home.how.match_body', 'Гіди теж переглядають відповідних гостей. Коли інтерес взаємний, ви спілкуєтеся й плануєте поїздку просто тут — навіть місце зустрічі можна надіслати.'),
